
const leaf='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.5 10.5h19"/><path d="m4 10.5 1.7 7.8a2 2 0 0 0 2 1.7h8.6a2 2 0 0 0 2-1.7l1.7-7.8"/><path d="m7 10.5 4-6.5M17 10.5l-4-6.5"/><path d="M9.5 13.5l.4 3.5M14.5 13.5l-.4 3.5"/></svg>';
const data=[{id:'seowon',name:'서원시장',count:28,x:104,y:140,distance:'494m',address:'부산 동래구 안락동',photo:'seowon.jpg'},{id:'myeong',name:'명장시장',count:17,x:300,y:80,distance:'820m',address:'부산 동래구 명장동',photo:'myeongjang.jpg'},{id:'chung',name:'충렬상가',count:9,x:316,y:185,distance:'650m',address:'부산 동래구 안락동'}];
let selected='seowon',filter='all',query='',saved=new Set();const $=id=>document.getElementById(id);let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2200)}
function render(){const visible=data.filter(m=>(!query||m.name.includes(query))&&(filter!=='near'||parseInt(m.distance)<700));$('pins').innerHTML=visible.map(m=>`<button class="pin ${selected===m.id?'active':''}" style="left:${m.x/390*100}%;top:${m.y}px" data-market="${m.id}" aria-label="${m.name}, 마감 상품 ${m.count}개" aria-pressed="${selected===m.id}">${leaf} ${m.count}</button><span class="pin-name" style="left:${m.x/390*100}%;top:${m.y}px">${m.name}</span>`).join('');if(!visible.length)toast('검색한 시장이 없어요');}
function select(id){selected=id;const m=data.find(m=>m.id===id);$('market-name').textContent=m.name;$('market-address').textContent=m.address;$('distance').textContent='내 위치에서 '+m.distance;$('count').textContent='마감 상품 '+m.count+'개';$('cta-label').textContent=m.name+' 마감 상품 보기';if(m.photo)$('market-photo').src=m.photo;$('market-photo').style.visibility=m.photo?'visible':'hidden';$('market-photo').alt=m.photo?m.name+' 입구':'';$('save').setAttribute('aria-pressed',saved.has(id));$('save').style.color=saved.has(id)?'#287454':'#7f8c81';render()}
$('pins').addEventListener('click',e=>{const b=e.target.closest('[data-market]');if(b)select(b.dataset.market)});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render();if(filter==='closing')toast('마감 상품이 있는 시장을 보고 있어요')}));$('search').addEventListener('input',e=>{query=e.target.value.trim();render()});$('save').addEventListener('click',()=>{saved.has(selected)?saved.delete(selected):saved.add(selected);select(selected);toast(saved.has(selected)?'관심 시장에 저장했어요':'관심 시장에서 해제했어요')});$('locate').addEventListener('click',()=>{filter='all';query='';$('search').value='';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));select('seowon');toast('내 위치 주변 시장이에요')});$('browse').addEventListener('click',()=>showScene('market'));$('location').addEventListener('click',()=>toast('현재 위치는 부산 안락동이에요'));document.querySelectorAll('[data-message]').forEach(b=>b.addEventListener('click',()=>toast(b.dataset.message)));document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>toast(b.textContent.trim()+' 화면으로 연결되는 탭이에요')));if(new URLSearchParams(location.search).has('capture'))document.body.classList.add('capture');render();

const goods=[{name:'손질 고등어 2마리',store:'형래네 생선가게',image:'mackerel-seller.png',price:4500,old:7000,discount:35,stock:'5팩',close:'18:00 마감'},{name:'수제 두부 1모',store:'시장 두부가게',image:'tofu-seller.png',price:2100,old:3000,discount:30,stock:'8모',close:'18:30 마감'},{name:'국내산 양배추 1통',store:'홍길네 채소가게',image:'cabbage-seller.png',price:2400,old:3200,discount:25,stock:'7통',close:'17:30 마감'}];
function drawGoods(){const q=document.getElementById('product-search').value.trim();const matches=goods.filter(g=>g.name.includes(q)||g.store.includes(q));const card=g=>`<button class="goods" data-product="${g.name}"><div class="goods-photo"><img src="assets/${g.image}" alt="${g.name}"><span>${g.close}</span></div><p class="goods-name">${g.name}</p><p class="goods-price"><em>${g.discount}%</em> ${g.price.toLocaleString()}원</p><p class="goods-old">${g.old.toLocaleString()}원</p><div class="goods-meta"><span>${g.store}</span><span>${g.stock} 남음</span></div></button>`;document.getElementById('discount-goods').innerHTML=[...matches].sort((a,b)=>b.discount-a.discount).map(card).join('');document.getElementById('closing-goods').innerHTML=[...matches].sort((a,b)=>a.close.localeCompare(b.close)).map(card).join('');document.querySelector('.list-empty').hidden=matches.length>0;document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>toast(b.dataset.product+' · 상품 상세는 다음 흐름에서 이어집니다.'))}
function showScene(scene){const list=document.querySelector('.market-view');list.hidden=scene!=='market';const m=data.find(m=>m.id===selected);document.getElementById('list-market-name').textContent=m.name;document.getElementById('list-distance').textContent='내 위치에서 '+m.distance;document.querySelectorAll('[data-scene]').forEach(b=>{b.classList.toggle('on',b.dataset.scene===scene);b.setAttribute('aria-pressed',b.dataset.scene===scene)});if(scene==='market')drawGoods()}
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{setRole(b.dataset.scene==='seller'?'seller':'buyer');if(b.dataset.scene!=='seller')showScene(b.dataset.scene)});document.getElementById('market-back').onclick=()=>showScene('home');document.getElementById('product-search').oninput=drawGoods;document.querySelectorAll('[data-list]').forEach(b=>b.onclick=()=>{const row=b.parentElement.nextElementSibling;row.classList.toggle('expanded');b.textContent=row.classList.contains('expanded')?'접기':'전체 보기 ↗'});document.getElementById('all-stores').onclick=()=>{const row=document.querySelector('.shop-row');row.classList.toggle('expanded');document.getElementById('all-stores').textContent=row.classList.contains('expanded')?'접기':'전체 보기 ↗'};document.querySelectorAll('[data-shop]').forEach(b=>b.onclick=()=>toast(b.dataset.shop+' · 가게 상세는 별도 흐름입니다.'));

let sellerTab='status',period='일';function setRole(role){const seller=role==='seller';document.querySelector('.seller-home').hidden=!seller;document.querySelectorAll('[data-role]').forEach(b=>{b.classList.toggle('active',b.dataset.role===role);b.setAttribute('aria-pressed',b.dataset.role===role)});document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('on',seller?b.dataset.scene==='seller':b.dataset.scene==='home'));if(seller)renderSeller()}
function renderSeller(){const panel=document.getElementById('seller-panel');document.querySelectorAll('[data-seller-tab]').forEach(b=>b.classList.toggle('on',b.dataset.sellerTab===sellerTab));if(sellerTab==='status'){const amount={'일':'100,000','주':'680,000','월':'2,840,000'};panel.innerHTML=`<div class="period-control">${['일','주','월'].map(p=>`<button class="${period===p?'on':''}" data-period="${p}">${p}</button>`).join('')}</div><div class="sales-summary"><p>${period==='일'?'오늘':period==='주'?'이번 주':'이번 달'} 총 판매액</p><strong>${amount[period]}원</strong><span>판매 현황을 한눈에 확인하세요</span></div><div class="seller-section-title"><h2>판매 카테고리</h2><button id="insight">성장 인사이트 ↗</button></div><div class="sales-chart"><div class="donut" role="img" aria-label="예시 판매 비중: 배추 30%, 양파 24%, 감자 18%, 대파 16%, 기타 12%"></div><div class="sales-legend">${['배추','양파','감자','대파','기타'].map((n,i)=>`<span><i style="background:${['#CF5B16','#E9915A','#F4C29E','#D7CBA5','#E8E6D9'][i]}"></i>${n}</span>`).join('')}</div></div>`;panel.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;renderSeller()});document.getElementById('insight').onclick=()=>toast('성장 인사이트는 확장 기능으로 계획한 화면입니다.')}else{panel.innerHTML=`<p class="market-note">오늘 판매한 상품 · 예시 내역</p>${[['cabbage-seller.png','국내산 배추','3포기','4,500'],['tofu-seller.png','수제 두부','2모','4,200'],['mackerel-seller.png','손질 고등어','1팩','4,500']].map(p=>`<div class="seller-list-row"><img src="assets/${p[0]}" alt="${p[1]}"><div><h3>${p[1]}</h3><p>판매 완료 · ${p[2]}</p></div><strong>${p[3]}원</strong></div>`).join('')}`}
panel.insertAdjacentHTML('beforeend','<div class="seller-quick"><button id="quick-register">상품 등록</button><button id="quick-manage">상품 관리</button></div><p class="seller-caption">판매액과 내역은 디자인 확인용 예시입니다.</p>');document.getElementById('quick-register').onclick=()=>toast('상품 등록 화면은 아래 02 판매자 상품 등록에서 볼 수 있어요.');document.getElementById('quick-manage').onclick=()=>toast('상품 관리 화면은 아래 05 판매 종료와 재고 관리에서 볼 수 있어요.')}
document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>setRole(b.dataset.role));document.querySelectorAll('[data-seller-tab]').forEach(b=>b.onclick=()=>{sellerTab=b.dataset.sellerTab;renderSeller()});document.getElementById('seller-bell').onclick=()=>toast('새로운 알림이 없어요.');const sellerIcons=['M4 8h16v12H4z M3 4h18v4H3z','M5 3h14v18H5z M12 8v8 M8 12h8','M3 10l9-7 9 7v11h-7v-7h-4v7H3z','M4 3h16v14h-8l-5 4v-4H4z','M8 6a4 4 0 108 0 4 4 0 00-8 0 M4 21v-3a8 5 0 0116 0v3'];document.querySelector('.seller-nav').innerHTML=['상품 관리','상품 등록','홈','도움말','마이페이지'].map((n,i)=>`<button data-seller-nav="${i}" class="${i===2?'active':''}"><svg viewBox="0 0 24 24"><path d="${sellerIcons[i]}"/></svg>${n}</button>`).join('');document.querySelectorAll('[data-seller-nav]').forEach(b=>b.onclick=()=>{const n=+b.dataset.sellerNav;if(n===0)toast('상품 관리 화면은 아래 05 판매 종료와 재고 관리에서 볼 수 있어요.');else if(n===1)toast('상품 등록 화면은 아래 02 판매자 상품 등록에서 볼 수 있어요.');else if(n===2)setRole('seller');else toast('판매자 '+b.textContent+' 화면입니다.')});
